import{_ as e,o,c as i,a2 as r}from"./chunks/framework.BWuWLRhz.js";const m=JSON.parse('{"title":"Analizador de espacio","description":"","frontmatter":{},"headers":[],"relativePath":"es-ES/user-guide/space-analyzer.md","filePath":"es-ES/user-guide/space-analyzer.md","lastUpdated":1787586465000}'),n={name:"es-ES/user-guide/space-analyzer.md"};function l(s,a,c,t,d,u){return o(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="analizador-de-espacio" tabindex="-1">Analizador de espacio <a class="header-anchor" href="#analizador-de-espacio" aria-label="Permalink to &quot;Analizador de espacio&quot;">​</a></h1><p>Lertaro incluye un <strong>Analizador de espacio (Space Analyzer)</strong> ultrarrápido para discos y carpetas. A diferencia de las herramientas tradicionales que requieren escaneos físicos completos de los sectores, aprovecha el árbol de índices en memoria de Lertaro para desglosar el almacenamiento en milisegundos, incluso en unidades con millones de archivos.</p><h2 id="_1-acceso-al-analizador-de-espacio" tabindex="-1">1. Acceso al Analizador de espacio <a class="header-anchor" href="#_1-acceso-al-analizador-de-espacio" aria-label="Permalink to &quot;1. Acceso al Analizador de espacio&quot;">​</a></h2><ul><li><strong>Aparición automática</strong>: Abre la Ventana principal de búsqueda (<code>Ctrl+F</code>) dejando la <strong>barra de búsqueda vacía</strong>; el Analizador de espacio se mostrará automáticamente como vista principal.</li><li><strong>Transición fluida</strong>: Escribir cualquier carácter cambia al instante a la lista de resultados de búsqueda; borrar la búsqueda regresa de inmediato a la vista del Analizador de espacio.</li></ul><h2 id="_2-diseno-y-visualizacion" tabindex="-1">2. Diseño y visualización <a class="header-anchor" href="#_2-diseno-y-visualizacion" aria-label="Permalink to &quot;2. Diseño y visualización&quot;">​</a></h2><p>El Analizador de espacio utiliza una disposición en dos paneles sincronizados para ofrecer máxima claridad:</p><h3 id="panel-izquierdo-grafico-treemap" tabindex="-1">Panel izquierdo: Gráfico Treemap <a class="header-anchor" href="#panel-izquierdo-grafico-treemap" aria-label="Permalink to &quot;Panel izquierdo: Gráfico Treemap&quot;">​</a></h3><ul><li><strong>Área proporcional</strong>: Los rectángulos más grandes corresponden a carpetas o archivos que ocupan mayor volumen de almacenamiento.</li><li><strong>Profundidad de color y bordes</strong>: El sombreado refleja el peso relativo dentro del directorio actual, con bordes diferenciados para distinguir carpetas de archivos individuales.</li></ul><h3 id="panel-derecho-lista-ordenada-por-tamano" tabindex="-1">Panel derecho: Lista ordenada por tamaño <a class="header-anchor" href="#panel-derecho-lista-ordenada-por-tamano" aria-label="Permalink to &quot;Panel derecho: Lista ordenada por tamaño&quot;">​</a></h3><ul><li><strong>Orden descendente</strong>: Lista los elementos ordenados de mayor a menor, identificando al instante los elementos que más espacio consumen.</li><li><strong>Barra de porcentaje</strong>: Cada fila incluye una sutil barra de progreso que indica su proporción respecto al total visible.</li><li><strong>Resaltado bidireccional</strong>: Al seleccionar un elemento en el Treemap o en la lista derecha, se enfoca simultáneamente en ambos paneles.</li><li><strong>Desplazamiento fluido de nombres largos</strong>: Los nombres que superen el ancho visible se desplazan suavemente al pasar el ratón o seleccionarlos.</li></ul><h2 id="_3-navegacion-y-operaciones-contextuales" tabindex="-1">3. Navegación y operaciones contextuales <a class="header-anchor" href="#_3-navegacion-y-operaciones-contextuales" aria-label="Permalink to &quot;3. Navegación y operaciones contextuales&quot;">​</a></h2><ul><li><strong>Exploración jerárquica</strong>: <ul><li><strong>Entrar en una carpeta</strong>: Haz doble clic izquierdo en cualquier tarjeta del Treemap o fila de la lista para explorar su interior.</li><li><strong>Subir de nivel</strong>: Haz clic en la flecha &quot;Arriba&quot; en la barra de navegación o en cualquier carpeta de la ruta de navegación (Breadcrumbs).</li></ul></li><li><strong>Menú de acciones contextual</strong>: Haz clic derecho en cualquier tarjeta o fila para abrir el <strong>Menú de acciones</strong> estándar (Abrir, Copiar ruta completa, Mostrar en Explorador, Enviar a la papelera o Eliminar permanentemente).</li><li><strong>Ubicar con clic central</strong>: Haz clic central en cualquier elemento para abrir y ubicar su posición en tu explorador de archivos configurado.</li><li><strong>Vista previa sincronizada</strong>: Pulsa <code>Alt+P</code> para abrir el panel de QuickLook; la vista previa se actualiza dinámicamente conforme navegas por los elementos.</li></ul><h2 id="_4-criterios-de-calculo-y-sincronizacion-en-tiempo-real" tabindex="-1">4. Criterios de cálculo y sincronización en tiempo real <a class="header-anchor" href="#_4-criterios-de-calculo-y-sincronizacion-en-tiempo-real" aria-label="Permalink to &quot;4. Criterios de cálculo y sincronización en tiempo real&quot;">​</a></h2><h3 id="ambito-y-calculo-de-tamanos" tabindex="-1">Ámbito y cálculo de tamaños <a class="header-anchor" href="#ambito-y-calculo-de-tamanos" aria-label="Permalink to &quot;Ámbito y cálculo de tamaños&quot;">​</a></h3><ul><li><strong>Basado en el índice existente</strong>: Solo resume los elementos indexados por Lertaro sin realizar operaciones de E/S adicionales en disco. Los archivos excluidos por reglas no se contabilizan.</li><li><strong>Tamaño lógico de archivos</strong>: Muestra los tamaños lógicos reales; los datos con enlaces físicos (hard links) solo se computan una vez para evitar duplicidades.</li><li><strong>Archivos ocultos y del sistema</strong>: Los archivos ocultos se incluyen con normalidad; los archivos del sistema se consolidan en el tamaño total de su carpeta superior.</li></ul><h3 id="seguimiento-de-cambios-y-autorrecuperacion" tabindex="-1">Seguimiento de cambios y autorrecuperación <a class="header-anchor" href="#seguimiento-de-cambios-y-autorrecuperacion" aria-label="Permalink to &quot;Seguimiento de cambios y autorrecuperación&quot;">​</a></h3><ul><li><strong>Actualizaciones en vivo</strong>: Recibe notificaciones de cambios del servicio de indexación y actualiza la vista de forma fluida.</li><li><strong>Recuperación automática de rutas</strong>: Si la carpeta activa es eliminada o renombrada externamente, el Analizador de espacio retrocede de forma inteligente a la carpeta superior válida más cercana sin bloquearse.</li></ul>',17)])])}const g=e(n,[["render",l]]);export{m as __pageData,g as default};
